WITH latest_match AS (SELECT s.*, latest.last_restock, latest.quantity FROM products s JOIN LATERAL (SELECT c.last_restock, c.quantity FROM inventory c WHERE c.product_id = s.id AND c.last_restock <= s.launch_date ORDER BY c.last_restock DESC, c.id DESC LIMIT 1) latest ON TRUE) SELECT s.id, s.product_name, s.brand, s.price, s.cost, s.launch_date, s.supplier_id, s.last_restock, (SELECT MAX(p2.cost) FROM products p2 WHERE p2.supplier_id = s.supplier_id) AS max_product_cost FROM latest_match s ORDER BY last_restock DESC, brand DESC
